const { useState, useEffect } = React;

const URL = '/api/courses';

function CourseList() {
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    fetch(URL)
      .then((res) => {
        if (!res.ok) throw new Error('실패');
        return res.json();
      })
      .then((list) => {
        setCourses(list);
        setLoading(false);
      })
      .catch(() => {
        setFailed(true);
        setLoading(false);
      });
  }, []);

  console.log('렌더 · loading=' + loading + ' failed=' + failed + ' 개수=' + courses.length);

  if (failed) return <p className="state">불러오지 못했습니다</p>;
  if (loading) return <p className="state">불러오는 중…</p>;
  if (courses.length === 0) return <p className="state">등록된 코스가 없습니다</p>;

  return (
    <div>
      <p className="state">코스 {courses.length}개</p>
      {courses.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseList />);

