const { useState, useEffect } = React;

function CourseList({ url }) {
  const [status, setStatus] = useState('loading');
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error('실패');
        return res.json();
      })
      .then((list) => {
        setCourses(list);
        null; // ← 여기를 채우세요
      })
      .catch(() => setStatus('error'));
  }, []);

  if (status === 'loading') return <p className="state">불러오는 중…</p>;
  if (status === 'error') return <p className="state">불러오지 못했습니다</p>;
  if (status === 'empty') return <p className="state">등록된 코스가 없습니다</p>;

  return (
    <div>
      <p className="state">코스 {courses.length}개</p>
      {courses.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
    </div>
  );
}

// 아래 셋은 그대로 두세요. 검사기가 show 를 부릅니다
const root = ReactDOM.createRoot(document.querySelector('#root'));

function waitFor(ok) {
  const el = document.querySelector('#root');
  return new Promise((resolve) => {
    const startedAt = Date.now();
    const tick = () => {
      if (ok(el.textContent) || Date.now() - startedAt > 3000) resolve(el.textContent);
      else setTimeout(tick, 30);
    };
    tick();
  });
}

function show(url) {
  root.render(<CourseList key={url} url={url} />);
  return waitFor((t) => t.includes('불러오는 중'))
    .then(() => waitFor((t) => t && !t.includes('불러오는 중')));
}

show('/api/courses');

